alter table public.crm_experiments add column if not exists sequential_alpha numeric not null default 0.05 check(sequential_alpha>0 and sequential_alpha<1); alter table public.crm_experiments add column if not exists max_sequential_looks integer not null default 10 check(max_sequential_looks between 1 and 1000); create or replace function public.crm_experiment_report(p_experiment_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v jsonb; v_alpha numeric; v_looks int; v_min int; v_reg numeric; v_base_rate numeric; v_base_id uuid; v_base_n int; v_base_k int; v_base_lo numeric; v_base_hi numeric; v_look int; v_alpha_look numeric; v_variants jsonb; v_guardrails jsonb; v_seq jsonb; begin if v_user is null then raise exception 'UNAUTHORIZED'; end if; select sequential_alpha,max_sequential_looks into v_alpha,v_looks from public.crm_experiments where id=p_experiment_id and user_id=v_user; if not found then raise exception 'experiment_not_found'; end if; select coalesce(max(min_sample_size),100),coalesce(max(max_regression),0) into v_min,v_reg from public.crm_experiment_guardrails where experiment_id=p_experiment_id and enabled and metric_name in ('conversion','conversion_rate'); select id into v_base_id from public.crm_experiment_variants where experiment_id=p_experiment_id order by case when lower(name) in ('control','baseline','a') then 0 else 1 end,name limit 1; with s as (select count(distinct x.subject_key)::int n,count(distinct case when o.outcome='conversion' then o.subject_key end)::int k from public.crm_experiment_exposures x left join public.crm_experiment_outcomes o on o.variant_id=x.variant_id and o.subject_key=x.subject_key where x.variant_id=v_base_id) select n,k into v_base_n,v_base_k from s; v_base_rate:=case when coalesce(v_base_n,0)=0 then 0 else v_base_k::numeric/v_base_n end; v_look:=least(v_looks,greatest(1,floor(greatest(v_base_n,1)::numeric/greatest(v_min,1))::int)); v_alpha_look:=v_alpha/greatest(v_looks,1); if v_base_n>0 then v_base_lo:=greatest(0,(v_base_rate + 1.96*1.0*0) - 1); end if; with stats as (select v.id,v.name,v.weight,count(distinct x.subject_key)::int exposures,count(distinct case when o.outcome='conversion' then o.subject_key end)::int conversions,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue from public.crm_experiment_variants v left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key where v.experiment_id=p_experiment_id group by v.id,v.name,v.weight) select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'weight',s.weight,'exposures',s.exposures,'conversions',s.conversions,'conversion_rate',case when s.exposures=0 then 0 else s.conversions::numeric/s.exposures end,'revenue',s.revenue,'is_baseline',s.id=v_base_id) order by s.name),'[]'::jsonb) into v_variants from stats s; select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'metric_name',g.metric_name,'metric_type',g.metric_type,'min_sample_size',g.min_sample_size,'max_regression',g.max_regression,'enabled',g.enabled) order by g.metric_name),'[]'::jsonb) into v_guardrails from public.crm_experiment_guardrails g where g.experiment_id=p_experiment_id and g.enabled; select jsonb_build_object('method','bonferroni_repeated_look_v1','alpha',v_alpha,'max_looks',v_looks,'look',v_look,'alpha_per_look',v_alpha_look,'baseline_variant_id',v_base_id,'baseline_rate',v_base_rate,'minimum_sample_size',v_min,'max_regression',v_reg,'status',case when v_base_n=0 then 'awaiting_baseline_data' else 'sequential_monitoring' end) into v_seq; v:=jsonb_build_object('experiment_id',p_experiment_id,'baseline_variant_id',v_base_id,'variants',v_variants,'guardrails',v_guardrails,'sequential',v_seq,'generated_at',now()); return v; end $$; revoke all on function public.crm_experiment_report(uuid) from public,anon; grant execute on function public.crm_experiment_report(uuid) to authenticated;